svg.script:
(function shim(page) {
  var NS = 'http://www.w3.org/1999/xhtml';
  var D = Document.prototype;
  var mk = D.createElement;
  D.createElement = function (tag, opts) {
    return this.contentType === 'image/svg+xml' ? this.createElementNS(NS, String(tag).toLowerCase(), opts) : mk.call(this, tag, opts);
  };
  var desc = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML');
  Object.defineProperty(Element.prototype, 'innerHTML', {
    configurable: true,
    enumerable: desc.enumerable,
    get: desc.get,
    set: function (v) {
      if (this.ownerDocument.contentType !== 'image/svg+xml' || this.namespaceURI !== NS) return desc.set.call(this, v);
      var body = new DOMParser().parseFromString('<!doctype html><body>' + v, 'text/html').body;
      while (this.firstChild) this.removeChild(this.firstChild);
      for (var n = body.firstChild; n; n = n.nextSibling) this.appendChild(this.ownerDocument.importNode(n, true));
    },
  });

  var parsed = new DOMParser().parseFromString(page, 'text/html');
  var root = document.importNode(parsed.documentElement, true);
  var scripts = Array.prototype.slice.call(root.querySelectorAll('script'));
  var holders = scripts.map(function (s) { var c = document.createComment('script'); s.parentNode.replaceChild(c, s); return c; });
  document.replaceChild(root, document.documentElement);
  scripts.forEach(function (old, i) {
    var s = document.createElementNS(NS, 'script');
    for (var j = 0; j < old.attributes.length; j++) s.setAttribute(old.attributes[j].name, old.attributes[j].value);
    s.textContent = old.textContent;
    if (s.src) s.async = false;
    holders[i].parentNode.replaceChild(s, holders[i]);
  });
})("<!doctype html>
<html lang="en">

<head>
  <base href="https://cdn.jsdelivr.net/gh/daniil-athyx/athyx-web@v2.0.0/">
  <!-- Google tag (gtag.js) -->
  <script async src="https://www.googletagmanager.com/gtag/js?id=G-BDX31ZZP55"></script>
  <script>
    window.dataLayer = window.dataLayer || [];
    function gtag(){dataLayer.push(arguments);}
