  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Athyx Network</title>
  <script>
    // Tab Cloaker: Immediately restore custom title on load/refresh before paint
    try {
      const savedCloakTitle = localStorage.getItem("athyx_tab_title");
      if (savedCloakTitle) document.title = savedCloakTitle;
    } catch(e) {}
  </script>
  <script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-6960985165305491" crossorigin="anonymous"></script>

  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700&family=Outfit:wght@500;600;700;800&display=swap" rel="stylesheet">
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" />
  <link rel="stylesheet" href="themes.css?v=6">
  <script src="js/themes.js?v=6"></script>
  <script src="js/cdn-config.js?v=1"></script>
  <script src="js/setup-wizard.js?v=1"></script>

  <!-- Scramjet and BareMux Proxy Scripts -->
  <script src="https://cdn.jsdelivr.net/npm/sortablejs@1.15.0/Sortable.min.js"></script>
  <script src="scramjet/JS/scramjet.all.js?v=9"></script>
  <script src="scramjet/B/index.js"></script>
  <script src="scramjet/prxxry.config.js"></script>

  <link rel="icon" type="image/png" href="assets/favicon.png">
  <link rel="shortcut icon" href="assets/favicon.ico">
  <script>
    // Tab Cloaker: Immediately restore custom favicon on load/refresh before browser loads default
    try {
      const savedCloakIcon = localStorage.getItem("athyx_tab_icon");
      if (savedCloakIcon) {
        document.querySelectorAll("link[rel*='icon']").forEach(el => el.href = savedCloakIcon);
      }
    } catch(e) {}

    // Synchronize cloak in real-time when changed from Settings
    window.addEventListener("storage", (e) => {
      if (e.key === "athyx_tab_title" || e.key === "athyx_tab_icon") {
        const title = localStorage.getItem("athyx_tab_title") || "Athyx Network";
        document.title = title;
        const icon = localStorage.getItem("athyx_tab_icon") || "assets/favicon.png";
        document.querySelectorAll("link[rel*='icon']").forEach(el => el.href = icon);
      }
    });
  </script>

  <style>
    @font-face {
      font-family: 'UltimateBlackMetal';
      src: url('assets/fonts/XXII-Ultimate-Black-Metal.ttf') format('truetype');
      font-weight: normal;
      font-style: normal;
      font-display: swap;
    }

    @font-face {
      font-family: 'XXII Ultimate-Black-Metal';
      src: url('assets/fonts/XXII-Ultimate-Black-Metal.ttf') format('truetype');
      font-weight: normal;
      font-style: normal;
      font-display: swap;
    }

    @font-face {
      font-family: 'Maskdown';
      src: url('assets/fonts/MaskdownOne-BWV7V.otf') format('opentype');
      font-weight: normal;
      font-style: normal;
      font-display: swap;
    }

    @font-face {
      font-family: 'Sabersong';
      src: url('assets/fonts/Sabersong-X38j2.ttf') format('truetype'),
           url('assets/fonts/Sabersong-L3Djy.otf') format('opentype');
      font-weight: normal;
      font-style: normal;
      font-display: swap;
    }

    :root {
      color-scheme: dark;
      --bg: #000000;
      --bg-base: #000000;
      --surface: rgba(255, 255, 255, 0.05);
      --surface-hover: rgba(255, 255, 255, 0.08);
      --surface-active: rgba(255, 255, 255, 0.12);
      --border: rgba(255, 255, 255, 0.1);
      --border-hover: rgba(255, 255, 255, 0.22);
      --border-light: rgba(255, 255, 255, 0.14);
      --dock-bg: rgba(8, 8, 8, 0.55);
      --dock-border: rgba(255, 255, 255, 0.12);
      --dock-btn-hover: rgba(255, 255, 255, 0.08);
      --dock-btn-active: rgba(255, 255, 255, 0.14);
      --text: #ffffff;
      --text-main: #ffffff;
      --text-muted: #a1a1aa;
      --text-dim: rgb(10, 255, 206);
      --accent: rgb(10, 255, 206);
      --accent-dim: rgba(10, 255, 206, 0.18);
      --accent-glow: rgba(10, 255, 206, 0.45);
      --accent-hover: rgb(0, 214, 174);
      --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
      --font-heading: 'Outfit', sans-serif;
    }

    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html, body {
      width: 100vw;
      height: 100vh;
      overflow: hidden;
      background-color: #000000;
      background-image: radial-gradient(rgba(255, 255, 255, 0.08) 1.25px, transparent 1.25px);
      background-size: 24px 24px;
      background-attachment: fixed;
      font-family: var(--font-sans);
      color: var(--text);
    }

    .flex {
      display: flex;
    }

    /* Full Proxy Browser Container Layout */
    .browser-container {
      width: 100vw;
      height: 100vh;
      color: var(--text);
      display: flex;
      flex-direction: column;
      background: #000000;
      position: relative;
      overflow: hidden;
    }

    /* Tabs Bar (Top) */
    .tabs {
      padding: 8px 12px 0;
      gap: 4px;
      overflow-x: auto;
      white-space: nowrap;
      background: rgba(0, 0, 0, 0.55);
      backdrop-filter: blur(20px) saturate(180%);
      -webkit-backdrop-filter: blur(20px) saturate(180%);
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      align-items: flex-end;
      scrollbar-width: none;
      position: relative;
      z-index: 10;
      transition: background-color 0.25s ease, border-color 0.25s ease;
    }

    .tabs::-webkit-scrollbar {
      display: none;
    }

    .tab {
      color: var(--text-muted);
      outline: none;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-bottom: none;
      border-radius: 10px 10px 0 0;
      background: rgba(255, 255, 255, 0.04);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      padding: 7px 14px;
      width: 220px;
      min-width: 160px;
      max-width: 260px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      display: flex;
      align-items: center;
      gap: 8px;
      cursor: pointer;
      flex-shrink: 0;
      transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
      font-size: 0.85rem;
      position: relative;
      user-select: none;
    }

    .tab:hover:not(.active) {
      background: rgba(255, 255, 255, 0.08);
      border-color: rgba(255, 255, 255, 0.14);
      color: var(--text);
      transform: translateY(-1px);
    }

    .tab.active {
      background: rgba(255, 255, 255, 0.12);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-color: rgba(255, 255, 255, 0.18);
      color: var(--text);
      box-shadow: 0 -2px 12px var(--accent-dim);
      position: relative;
      z-index: 2;
    }

    .tab.active::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 2px;
      background: var(--accent);
      border-radius: 10px 10px 0 0;
      box-shadow: 0 0 8px var(--accent-glow);
    }

    .tab-favicon {
      width: 15px;
      height: 15px;
      flex-shrink: 0;
      border-radius: 3px;
      display: block;
    }

    .tab-favicon[src=""], .tab-favicon:not([src]) {
      display: none;
    }

    .tab-icon {
      font-size: 13px;
      color: var(--accent);
      flex-shrink: 0;
    }

    .tab-title {
      flex: 1;
      overflow: hidden;
      text-overflow: ellipsis;
      font-weight: 500;
      letter-spacing: -0.01em;
    }

    .tab-close {
      background: transparent;
      border: none;
      color: var(--text-muted);
      cursor: pointer;
      font-size: 11px;
      border-radius: 6px;
      width: 22px;
      height: 22px;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 0;
      margin: 0;
      line-height: 1;
      transition: all 0.15s ease;
      flex-shrink: 0;
    }

    .tab-close i {
      font-size: 11px;
      display: flex;
      align-items: center;
      justify-content: center;
      transform: none !important;
    }

    .tab-close:hover {
      background: rgba(255, 255, 255, 0.12);
      color: #ff5c7c;
      transform: none !important;
    }

    .tab-close:hover i {
      transform: none !important;
    }

    .new-tab {
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid rgba(255, 255, 255, 0.08);
      color: var(--text-muted);
      border-radius: 8px;
      width: 28px;
      height: 28px;
      margin-bottom: 4px;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 0;
      cursor: pointer;
      font-size: 11px;
      flex-shrink: 0;
      transition: all 0.2s ease;
      line-height: 1;
    }

    .new-tab i {
      font-size: 11px;
      display: flex;
      align-items: center;
      justify-content: center;
      transform: none !important;
    }

    .new-tab:hover {
      background: rgba(255, 255, 255, 0.1);
      border-color: rgba(255, 255, 255, 0.16);
      color: var(--text);
      transform: scale(1.05);
    }

    .new-tab:hover i {
      transform: none !important;
    }

    /* Nav & Address Bar */
    .nav {
      padding: 8px 14px;
      gap: 8px;
      background: rgba(0, 0, 0, 0.65);
      backdrop-filter: blur(20px) saturate(180%);
      -webkit-backdrop-filter: blur(20px) saturate(180%);
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      align-items: center;
      z-index: 9;
      transition: background-color 0.25s ease, border-color 0.25s ease;
    }

    .nav button {
      color: var(--text-muted);
      outline: none;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 10px;
      background: rgba(255, 255, 255, 0.05);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      padding: 8px 13px;
      cursor: pointer;
      transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
      font-size: 0.95rem;
      display: flex;
      align-items: center;
      justify-content: center;
      min-width: 36px;
      height: 36px;
    }

    .nav button:hover {
      background: rgba(255, 255, 255, 0.12);
      border-color: var(--accent);
      color: var(--text);
      box-shadow: 0 0 12px var(--accent-dim);
      transform: translateY(-1px);
    }

    .nav button:active {
      transform: translateY(0);
    }

    input.bar {
      font-family: var(--font-sans);
      padding: 8px 16px;
      border: 1px solid rgba(255, 255, 255, 0.1);
      outline: none;
      color: var(--text);
      border-radius: 12px;
      flex: 1;
      background: rgba(255, 255, 255, 0.05);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      font-size: 0.92rem;
      transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
      height: 36px;
    }

    input.bar:hover {
      border-color: rgba(255, 255, 255, 0.18);
      background: rgba(255, 255, 255, 0.08);
    }

    input.bar:focus {
      background: rgba(255, 255, 255, 0.1);
      border-color: var(--accent);
      box-shadow: 0 0 0 2px var(--accent-dim), 0 4px 16px rgba(0, 0, 0, 0.4);
    }

    input.bar::placeholder {
      color: rgba(255, 255, 255, 0.45);
      transition: color 0.2s ease, opacity 0.2s ease;
    }

    /* Focused on built-in Athyx tab: transparent bar & translucent URL placeholder */
    input.bar.built-in-focused,
    input.bar.built-in-focused:focus {
      background: rgba(255, 255, 255, 0.03) !important;
      border-color: rgba(255, 255, 255, 0.22) !important;
      box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.14), 0 4px 18px rgba(0, 0, 0, 0.5) !important;
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      color: #ffffff;
    }

    input.bar.built-in-focused::placeholder {
      color: rgba(255, 255, 255, 0.38) !important;
      opacity: 1 !important;
    }

    /* Loading Bar */
    .loading-bar-container {
      width: 100%;
      height: 2px;
      background: transparent;
      overflow: hidden;
      position: relative;
      z-index: 8;
    }

    .loading-bar {
      height: 100%;
      width: 0%;
      background: var(--accent);
      box-shadow: 0 0 10px var(--accent-glow);
      transition: width 0.2s ease, opacity 0.3s ease;
    }

    /* Iframe Container */
    .iframe-container {
      flex: 1;
      width: 100%;
      height: 100%;
      position: relative;
      overflow: hidden;
      background: #000;
    }

    .iframe-container iframe {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      border: none;
      background: #000;
      display: block;
    }

    .iframe-container iframe.hidden {
      display: none !important;
    }

    /* Floating App Bar (Dock) Position Variants: Bottom, Left, Right */
    .dock-wrapper {
      position: fixed;
      bottom: 6px;
      left: 50%;
      transform: translateX(-50%);
      z-index: 1000;
      display: flex;
      flex-direction: row;
      align-items: center;
      padding: 5px 10px;
      background: var(--dock-bg);
      backdrop-filter: blur(24px) saturate(190%);
      -webkit-backdrop-filter: blur(24px) saturate(190%);
      border: 1px solid var(--dock-border);
      border-radius: 18px;
      box-shadow:
        0 20px 40px -15px rgba(0, 0, 0, 0.6),
        0 0 0 1px rgba(255, 255, 255, 0.04),
        inset 0 1px 0 rgba(255, 255, 255, 0.1);
      gap: 6px;
      user-select: none;
      transition: transform 0.28s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.22s ease, left 0.25s ease, right 0.25s ease, bottom 0.25s ease, top 0.25s ease;
    }

    /* Hidden state */
    .dock-wrapper.dock-hidden {
      transform: translate(-50%, calc(100% + 20px));
      opacity: 0;
      pointer-events: none;
    }

    .dock-wrapper.dock-hidden:hover {
      opacity: 1;
      pointer-events: auto;
    }

    .dock-wrapper.dock-game-hidden {
      transform: translate(-50%, calc(100% + 40px)) !important;
      opacity: 0 !important;
      pointer-events: none !important;
    }

    /* Left Position */
    .dock-wrapper.dock-pos-left {
      top: 50%;
      left: 16px;
      bottom: auto;
      right: auto;
      transform: translateY(-50%);
      flex-direction: column;
      padding: 12px 6px;
      border-radius: 20px;
    }

    .dock-wrapper.dock-pos-left.dock-hidden {
      transform: translate(calc(-100% - 10px), -50%);
      opacity: 0.85;
    }

    .dock-wrapper.dock-pos-left.dock-game-hidden {
      transform: translate(calc(-100% - 40px), -50%) !important;
      opacity: 0 !important;
      pointer-events: none !important;
    }

    /* Right Position */
    .dock-wrapper.dock-pos-right {
      top: 50%;
      right: 16px;
      bottom: auto;
      left: auto;
      transform: translateY(-50%);
      flex-direction: column;
      padding: 12px 6px;
      border-radius: 20px;
    }

    .dock-wrapper.dock-pos-right.dock-hidden {
      transform: translate(calc(100% + 10px), -50%);
      opacity: 0.85;
    }

    .dock-wrapper.dock-pos-right.dock-game-hidden {
      transform: translate(calc(100% + 40px), -50%) !important;
      opacity: 0 !important;
      pointer-events: none !important;
    }

    /* Compact Dock Mode (Icons only) */
    .dock-wrapper.dock-compact .dock-item {
      padding: 8px 10px;
    }

    .dock-wrapper.dock-compact .dock-item span {
      display: none !important;
    }

    /* Vertical separators for left/right */
    .dock-wrapper.dock-pos-left .dock-separator,
    .dock-wrapper.dock-pos-right .dock-separator {
      width: 22px;
      height: 1px;
      margin: 3px 0;
    }

    .dock-trigger-zone {
      position: fixed;
      bottom: 0;
      left: 0;
      width: 100%;
      height: 16px;
      z-index: 999;
      pointer-events: auto;
      background: transparent;
    }

    .dock-trigger-zone.trigger-pos-left {
      top: 0;
      left: 0;
      bottom: 0;
      right: auto;
      width: 16px;
      height: 100%;
    }

    .dock-trigger-zone.trigger-pos-right {
      top: 0;
      right: 0;
      bottom: 0;
      left: auto;
      width: 16px;
      height: 100%;
    }

    .dock-item {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 8px 14px;
      font-size: 13.5px;
      font-weight: 500;
      color: var(--text-muted);
      background: transparent;
      border: 1px solid transparent;
      border-radius: 12px;
      cursor: pointer;
      font-family: inherit;
      transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
      position: relative;
      white-space: nowrap;
    }

    .dock-item i {
      font-size: 14px;
      color: var(--text-muted);
      transition: color 0.2s ease, transform 0.2s ease;
    }

    .dock-item:hover {
      color: var(--text-main);
      background: var(--dock-btn-hover);
      border-color: rgba(255, 255, 255, 0.08);
    }

    .dock-item:hover i {
      color: var(--text-main);
      transform: scale(1.08);
    }

    .dock-item.active {
      color: #ffffff;
      background: var(--dock-btn-active);
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
      border-color: rgba(255, 255, 255, 0.22);
      box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.15);
      font-weight: 600;
    }

    .dock-item.active i {
      color: var(--accent);
    }

    .dock-separator {
      width: 1px;
      height: 22px;
      background: var(--dock-border);
      margin: 0 3px;
    }

    /* Modals & Alerts */
    .custom-alert { position: fixed; inset: 0; z-index: 99999; display: none; align-items: center; justify-content: center; padding: 16px; background: rgba(0, 0, 0, 0.78); backdrop-filter: blur(8px); }
    .custom-alert.open { display: flex; animation: alertFadeIn 0.2s cubic-bezier(0.16, 1, 0.3, 1); }
    .custom-alert-card { width: min(440px, 92vw); background: var(--surface); border: 1px solid var(--border); border-radius: 20px; padding: 24px; text-align: center; box-shadow: 0 24px 80px rgba(0, 0, 0, 0.55); display: flex; flex-direction: column; gap: 12px; align-items: center; color: var(--text-main); }
    .custom-alert-title { margin: 0; font-family: 'Outfit', sans-serif; font-size: 18px; font-weight: 700; color: var(--text-main); }
    .custom-alert-text { margin: 0; font-size: 14px; color: var(--text-muted); line-height: 1.4; margin-bottom: 8px; width: 100%; text-align: left; }
    .custom-alert-btn { width: 100%; border: none; padding: 10px; border-radius: 10px; font-weight: bold; cursor: pointer; background: var(--accent); color: #000; transition: filter 0.2s; }
    .custom-alert-btn:hover { filter: brightness(1.1); }
    @keyframes alertFadeIn { from { opacity: 0; transform: translateY(10px) scale(0.95); } to { opacity: 1; transform: translateY(0) scale(1); } }

    /* WISP Modal */
    .modal-overlay { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.75); backdrop-filter: blur(8px); display: flex; align-items: center; justify-content: center; z-index: 99998; opacity: 1; transition: opacity 0.2s ease; }
    .modal-overlay.hidden { display: none !important; opacity: 0; pointer-events: none; }
    .wisp-settings-container { background: var(--surface); border: 1px solid var(--border); border-radius: 20px; width: 90%; max-width: 500px; padding: 20px; box-shadow: 0 24px 80px rgba(0, 0, 0, 0.6); display: flex; flex-direction: column; gap: 16px; }
    .modal-header { display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid var(--border); padding-bottom: 12px; }
    .modal-header h3 { font-family: var(--font-heading); font-size: 18px; color: var(--text); }
    .modal-close-btn { background: transparent; border: none; color: var(--text-muted); cursor: pointer; font-size: 18px; display: flex; align-items: center; justify-content: center; width: 28px; height: 28px; border-radius: 8px; }
    .modal-close-btn:hover { background: var(--surface-hover); color: var(--text); }
    .modal-close-btn svg { width: 18px; height: 18px; }
    .wisp-option { background: var(--surface-hover); border: 1px solid var(--border); border-radius: 10px; padding: 10px 14px; margin-bottom: 8px; cursor: pointer; display: flex; justify-content: space-between; align-items: center; transition: all 0.2s ease; }
    .wisp-option:hover { border-color: var(--accent); background: var(--surface-active); }
    .wisp-option.selected { border-color: var(--accent); background: var(--dock-btn-active); }
    .wisp-option-name { font-size: 13.5px; font-weight: 500; color: var(--text); }
    .modal-footer { display: flex; justify-content: flex-end; gap: 10px; border-top: 1px solid var(--border); padding-top: 12px; }
    .btn { padding: 8px 16px; border-radius: 8px; font-size: 13px; font-weight: 600; cursor: pointer; border: none; font-family: inherit; }
    .btn-secondary { background: var(--surface-hover); color: var(--text); border: 1px solid var(--border); }
    .btn-primary { background: var(--accent); color: #000; }
    .btn-primary:disabled { opacity: 0.5; cursor: not-allowed; }

    @media (max-width: 768px) {
      .dock-wrapper {
        bottom: 4px;
        padding: 4px 8px;
        gap: 4px;
        max-width: calc(100vw - 24px);
        overflow-x: auto;
      }
      .dock-wrapper.dock-hidden {
        transform: translate(-50%, calc(100% - 4px));
      }
      .dock-item {
        padding: 7px 10px;
        font-size: 12px;
      }
      .dock-item span {
        display: none;
      }
    }
  </style>
</head>

<body>
  <!-- Browser Chrome Layout -->
  <div class="browser-container">
    <!-- Tabs Bar -->
    <div class="flex tabs" id="tabs-container"></div>

    <!-- Navigation & Address Bar -->
    <div class="flex nav">
      <button id="back-btn" title="Back"><i class="fa-solid fa-chevron-left"></i></button>
      <button id="fwd-btn" title="Forward"><i class="fa-solid fa-chevron-right"></i></button>
      <button id="reload-btn" title="Reload"><i class="fa-solid fa-rotate-right"></i></button>
      <input class="bar" id="address-bar" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" placeholder="ath://home">
      <button id="devtools-btn" title="Developer Tools"><i class="fa-solid fa-code"></i></button>
      <button id="wisp-settings-btn" title="Proxy Settings"><i class="fa-solid fa-cog"></i></button>
      <button id="open-new-window-btn" title="Open in New Window"><i class="fa-solid fa-arrow-up-right-from-square"></i></button>
    </div>

    <!-- Loading Bar -->
    <div class="loading-bar-container">
      <div class="loading-bar" id="loading-bar"></div>
    </div>

    <!-- Multiple Tabs Viewport Container -->
    <div class="iframe-container" id="iframe-container"></div>
  </div>

  <!-- Bottom Dock Autohide Trigger Zone -->
  <div class="dock-trigger-zone" id="dockTriggerZone"></div>

  <!-- Bottom Floating App Bar (Dock) -->
  <div class="dock-wrapper dock-hidden" id="dockNav" role="navigation" aria-label="Main Navigation">
    <button class="dock-item active" data-tab="home" onclick="navigateRoute('ath://home')" title="Home">
      <i class="fa-solid fa-house"></i>
      <span>Home</span>
    </button>
    <button class="dock-item" data-tab="games" onclick="navigateRoute('ath://games')" title="Games">
      <i class="fa-solid fa-gamepad"></i>
      <span>Games</span>
    </button>
    <button class="dock-item" data-tab="apps" onclick="navigateRoute('ath://apps')" title="Apps">
      <i class="fa-solid fa-shapes"></i>
      <span>Apps</span>
    </button>
    <button class="dock-item" data-tab="proxy" onclick="navigateRoute('ath://hometab')" title="Browser">
      <i class="fa-solid fa-compass"></i>
      <span>Browser</span>
    </button>
    <button class="dock-item" data-tab="ai" onclick="navigateRoute('ath://ai')" title="AI Assistant">
      <i class="fa-solid fa-robot"></i>
      <span>AI</span>
    </button>
    <button class="dock-item" data-tab="cloud" onclick="navigateRoute('ath://cloud')" title="Proxy/Cloud Games">
      <i class="fa-solid fa-cloud"></i>
      <span>Proxy/Cloud</span>
    </button>
    <button class="dock-item" data-tab="music" onclick="navigateRoute('ath://music')" title="Music">
      <i class="fa-solid fa-music"></i>
      <span>Music</span>
    </button>
    <div class="dock-separator"></div>
    <button class="dock-item" data-tab="settings" onclick="navigateRoute('ath://settings')" title="Settings">
      <i class="fa-solid fa-sliders"></i>
      <span>Settings</span>
    </button>
  </div>

  <div id="global-notification-container" style="position:fixed; top:70px; left:20px; z-index:9999; display:flex; flex-direction:column; gap:10px; pointer-events:none;"></div>

  <!-- Update Log Modal -->
  <div id="update-modal" class="custom-alert" aria-hidden="true">
    <div class="custom-alert-card">
      <h3 class="custom-alert-title" id="update-title">Update log:</h3>
      <div class="custom-alert-text" id="update-changes" style="max-height: 200px; overflow-y: auto;"></div>
      <button class="custom-alert-btn" id="update-close">Awesome!</button>
    </div>
  </div>

  <!-- WISP Settings Modal -->
  <div class="wisp-settings-modal modal-overlay hidden" id="wisp-settings-modal">
    <div class="modal-container wisp-settings-container">
      <div class="modal-header">
        <h3>Proxy Settings</h3>
        <button class="modal-close-btn" id="close-wisp-modal" title="Close Settings">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor">
            <path d="M18 6 6 18M6 6l12 12" />
          </svg>
        </button>
      </div>
      <div class="modal-body" style="max-height: 320px; overflow-y: auto;">
        <div class="predefined-wisps" id="dynamic-wisps-container">
          <div style="font-size: 13px; color: var(--text-muted); padding: 10px;">Loading WISP proxy servers...</div>
        </div>
      </div>
      <div class="modal-footer">
        <button class="btn btn-secondary" id="close-wisp-modal-footer">Close</button>
        <button class="btn btn-primary" id="apply-wisp-btn" disabled>Apply Changes</button>
      </div>
    </div>
  </div>

  <script>
    // Internal Athyx Routes configuration
    const ATH_ROUTES = {
      'ath://home': {
        key: 'home',
        src: 'pages/homepage.html',
        title: 'Home',
        icon: 'fa-house'
      },
      'ath://games': {
        key: 'games',
        src: 'pages/g.html',
        title: 'Games',
        icon: 'fa-gamepad'
      },
      'ath://apps': {
        key: 'apps',
        src: 'pages/apps.html',
        title: 'Apps',
        icon: 'fa-shapes'
      },
      'ath://hometab': { key: 'proxy', src: 'scramjet/NT.html',
        title: 'New Tab',
        icon: 'fa-compass'
      },
      'scram://hometab': {
        key: 'proxy',
        src: 'scramjet/NT.html',
        title: 'New Tab',
        icon: 'fa-compass'
      },
      'ath://browser': {
        key: 'proxy',
        src: 'scramjet/NT.html',
        title: 'New Tab',
        icon: 'fa-compass'
      },
      'ath://cloud': {
        key: 'cloud',
        src: 'pages/cloud.html',
        title: 'Proxy/Cloud Games',
        icon: 'fa-cloud'
      },
      'ath://ai': {
        key: 'ai',
        src: 'https://toolbaz.com/writer/chat-gpt-alternative',
        proxy: true,
        title: 'AI Assistant',
        icon: 'fa-robot'
      },
      'ath://music': {
        key: 'music',
        src: 'pages/music.html',
        title: 'Music',
        icon: 'fa-music'
      },
      'ath://settings': {
        key: 'settings',
        src: 'pages/settings.html',
        title: 'Settings',
        icon: 'fa-sliders'
      },
      'scram://settings': {
        key: 'settings',
        src: 'pages/settings.html',
        title: 'Settings',
        icon: 'fa-sliders'
      }
    };

    // Scramjet Proxy Controller setup
    let scramjet = null;
    let bareMuxConn = null;

    try {
      if (typeof $scramjetLoadController === 'function') {
        const { ScramjetController } = $scramjetLoadController();
        scramjet = new ScramjetController({
          prefix: '/scramjet/JS/scramjet/',
          files: {
            wasm: '/scramjet/JS/scramjet.wasm.wasm',
            all: '/scramjet/JS/scramjet.all.js',
            sync: '/scramjet/JS/scramjet.sync.js',
          },
          flags: {
            serviceworkers: true,
            syncxhr: true,
            allowInvalidJs: true,
            allowFailedIntercepts: true,
          },
        });
        scramjet.init();
      }

      if (typeof BareMux !== 'undefined' && BareMux.BareMuxConnection) {
        bareMuxConn = new BareMux.BareMuxConnection('/scramjet/B/worker.js');
        const defaultWisp = localStorage.getItem("proxServer") || (typeof _CONFIG !== 'undefined' ? _CONFIG.wispurl : "wss://new-server.baylib.top/connection/");
        bareMuxConn.setTransport('/scramjet/Ep/index.mjs', [{ wisp: defaultWisp }]).catch(e => console.warn(e));
      }

      if ('serviceWorker' in navigator) {
        navigator.serviceWorker.register('/scramjet/sw.js', { scope: '/' }).catch(e => console.warn(e));
      }
    } catch(e) {
      console.warn('Scramjet proxy initialization error:', e);
    }

    // Tab state management
    let tabs = [];
    let activeTabId = null;
    let nextTabId = 1;
    let sortableInstance = null;

    const tabsContainer = document.getElementById("tabs-container");
    const iframeContainer = document.getElementById("iframe-container");
    const addressBar = document.getElementById("address-bar");
    const loadingBar = document.getElementById("loading-bar");
    const dockNav = document.getElementById("dockNav");

    function getActiveTab() {
      return tabs.find(t => t.id === activeTabId);
    }

    function unwrapUrl(url) {
      if (!url || typeof url !== "string") return "";
      if (url.startsWith("ath://")) return url;
      if (url.includes("pages/g.html")) return "ath://games";
      if (url.includes("pages/apps.html")) return "ath://apps";
      if (url.includes("pages/homepage.html")) return "ath://home";
      if (url.includes("pages/cloud.html")) return "ath://cloud";
      if (url.includes("pages/settings.html")) return "ath://settings";
      if (url.includes("NT.html")) return "ath://hometab";
      const marker = "/scramjet/JS/scramjet/";
      let current = url;
      while (current.includes(marker)) {
        const idx = current.indexOf(marker);
        const rest = current.slice(idx + marker.length);
        try {
          current = decodeURIComponent(rest);
        } catch(e) {
          current = rest;
        }
      }
      return current;
    }

    function syncBottomDockWithRoute(routeUrl) {
      const clean = (routeUrl || "").toLowerCase();
      let activeKey = null;
      for (const [key, val] of Object.entries(ATH_ROUTES)) {
        if (clean === key || clean.endsWith(val.src)) {
          activeKey = val.key;
          break;
        }
      }
      document.querySelectorAll(".dock-item").forEach(btn => {
        btn.classList.toggle("active", btn.getAttribute("data-tab") === activeKey);
      });
      document.body.classList.toggle("route-music", activeKey === "music");
    }

    function isAthyxBuiltInTab(url) {
      if (!url) return true;
      const clean = unwrapUrl(url);
      if (!clean) return true;
      if (clean.startsWith("ath://") || clean.startsWith("scram://")) return true;
      if (clean === "about:blank" || clean.endsWith("NT.html") || clean.includes("pages/")) return true;
      return false;
    }

    function updateAddressBar() {
      const activeTab = getActiveTab();
      if (!addressBar) return;
      if (!activeTab) {
        addressBar.value = "";
        addressBar.placeholder = "ath://hometab";
        addressBar.classList.remove("built-in-focused");
        return;
      }
      const clean = unwrapUrl(activeTab.url);
      const isBuiltIn = isAthyxBuiltInTab(activeTab.url);
      const displayUrl = clean || "ath://hometab";

      if (document.activeElement === addressBar) {
        if (isBuiltIn) {
          addressBar.dataset.builtinUrl = displayUrl;
          addressBar.placeholder = displayUrl;
          if (!addressBar.value) {
            addressBar.classList.add("built-in-focused");
          }
        } else {
          addressBar.classList.remove("built-in-focused");
        }
        syncBottomDockWithRoute(clean);
        return;
      }

      addressBar.classList.remove("built-in-focused");
      addressBar.dataset.builtinUrl = displayUrl;
      addressBar.value = displayUrl;
      addressBar.placeholder = isBuiltIn ? displayUrl : "Search or enter URL...";
      syncBottomDockWithRoute(clean);
    }

    function updateLoadingBar(progress) {
      if (!loadingBar) return;
      if (progress >= 100) {
        loadingBar.style.width = "100%";
        setTimeout(() => {
          loadingBar.style.opacity = "0";
          setTimeout(() => { loadingBar.style.width = "0%"; }, 200);
        }, 150);
      } else {
        loadingBar.style.opacity = "1";
        loadingBar.style.width = Math.max(15, progress) + "%";
      }
    }

    function createTab(initialRoute = 'ath://home', makeActive = true) {
      const iframe = document.createElement("iframe");
      iframe.setAttribute("allow", "autoplay; fullscreen; gamepad; clipboard-read; clipboard-write; cross-origin-isolated");
      iframe.title = "Athyx Content Frame";
      iframeContainer.appendChild(iframe);

      const tab = {
        id: nextTabId++,
        title: "Loading...",
        url: initialRoute,
        icon: "fa-house",
        favicon: "",
        frame: iframe,
        loading: true,
        progress: 20
      };

      tabs.push(tab);

      iframe.addEventListener("load", () => {
        tab.loading = false;
        tab.progress = 100;
        updateLoadingBar(100);

        try {
          const docTitle = iframe.contentWindow.document.title;
          if (docTitle && !tab.url.startsWith("ath://")) {
            tab.title = docTitle;
          }
        } catch(e) {}

        try {
          bindIframeMouseEvents(iframe);
        } catch(e) {}

        updateTabsUI();
      });

      iframe.addEventListener("error", () => {
        tab.loading = false;
        updateLoadingBar(100);
      });

      // Load initial route
      navigateTo(tab, initialRoute);

      if (makeActive) {
        switchTab(tab.id);
      } else {
        iframe.classList.add("hidden");
        updateTabsUI();
      }

      return tab;
    }

    function navigateTo(tab, targetUrl) {
      if (!tab) return;
      let url = (targetUrl || "").trim();
      if (!url) url = "ath://hometab";

      const lower = url.toLowerCase();
      const match = ATH_ROUTES[lower];

      tab.loading = true;
      updateLoadingBar(30);

      if (match) {
        tab.url = lower;
        tab.title = match.title;
        tab.icon = match.icon;
        tab.favicon = "";
        if (match.proxy && scramjet) {
          tab.frame.src = scramjet.encodeUrl(match.src);
        } else {
          const fullSrc = new URL(match.src, document.baseURI).href;
          fetch(fullSrc)
            .then(res => res.text())
            .then(pageHtml => {
              const baseUrl = fullSrc.substring(0, fullSrc.lastIndexOf('/') + 1);
              const patched = pageHtml.replace(/<head[^>]*>/i, function(m) {
                return m + '\n  <base href="' + baseUrl + '">';
              });
              tab.frame.srcdoc = patched;
            })
            .catch(function() {
              tab.frame.src = match.src + "?v=" + Date.now();
            });
        }
      } else {
        // External Web URL or Search
        let fullUrl = url;
        if (!fullUrl.match(/^https?:\/\//i)) {
          if (fullUrl.includes(".") && !fullUrl.includes(" ")) {
            fullUrl = "https://" + fullUrl;
          } else {
            fullUrl = "https://search.brave.com/search?q=" + encodeURIComponent(fullUrl);
          }
        }
        tab.url = fullUrl;
        tab.title = new URL(fullUrl).hostname;
        tab.icon = "fa-globe";
        try {
          tab.favicon = new URL(fullUrl).origin + "/favicon.ico";
        } catch(e) {
          tab.favicon = "";
        }
        if (scramjet) {
          tab.frame.src = scramjet.encodeUrl(fullUrl);
        } else {
          tab.frame.src = fullUrl;
        }
      }

      if (tab.id === activeTabId) {
        updateAddressBar();
      }
      updateTabsUI();
    }

    function switchTab(tabId) {
      activeTabId = tabId;
      tabs.forEach(t => {
        if (t.id === tabId) {
          t.frame.classList.remove("hidden");
        } else {
          t.frame.classList.add("hidden");
        }
      });
      updateTabsUI();
      updateAddressBar();

      // Check if the newly active tab has an active game/app
      const activeTab = getActiveTab();
      if (activeTab && activeTab.isGameActive) {
        isGameFullscreenActive = true;
        dockNav.classList.add("dock-game-hidden");
      } else {
        isGameFullscreenActive = false;
        dockNav.classList.remove("dock-game-hidden");
        showDock();
      }
    }

    function closeTab(tabId) {
      const idx = tabs.findIndex(t => t.id === tabId);
      if (idx === -1) return;
      const removed = tabs.splice(idx, 1)[0];
      if (removed.frame && removed.frame.parentNode) {
        removed.frame.remove();
      }
      if (activeTabId === tabId) {
        if (tabs.length > 0) {
          const nextIdx = Math.min(idx, tabs.length - 1);
          switchTab(tabs[nextIdx].id);
        } else {
          createTab('ath://hometab', true);
        }
      } else {
        updateTabsUI();
      }
    }

    function updateTabsUI() {
      if (!tabsContainer) return;
      tabsContainer.innerHTML = "";

      tabs.forEach(tab => {
        const tabEl = document.createElement("div");
        tabEl.className = `tab ${tab.id === activeTabId ? "active" : ""}`;
        tabEl.setAttribute("data-tab-id", tab.id);
        tabEl.onclick = () => switchTab(tab.id);

        if (tab.favicon) {
          const favImg = document.createElement("img");
          favImg.className = "tab-favicon";
          favImg.src = tab.favicon;
          favImg.onerror = () => { favImg.style.display = "none"; };
          tabEl.appendChild(favImg);
        } else {
          const iconEl = document.createElement("i");
          iconEl.className = `fa-solid ${tab.icon || "fa-globe"} tab-icon`;
          tabEl.appendChild(iconEl);
        }

        const titleEl = document.createElement("span");
        titleEl.className = "tab-title";
        titleEl.textContent = tab.title || "New Tab";
        tabEl.appendChild(titleEl);

        const closeBtn = document.createElement("button");
        closeBtn.className = "tab-close";
        closeBtn.innerHTML = '<i class="fa-solid fa-xmark"></i>';
        closeBtn.title = "Close tab";
        closeBtn.onclick = (e) => {
          e.stopPropagation();
          closeTab(tab.id);
        };
        tabEl.appendChild(closeBtn);

        tabsContainer.appendChild(tabEl);
      });

      const newBtn = document.createElement("button");
      newBtn.className = "new-tab";
      newBtn.innerHTML = '<i class="fa-solid fa-plus"></i>';
      newBtn.title = "New Tab";
      newBtn.onclick = () => {
        createTab('ath://hometab', true);
      };
      tabsContainer.appendChild(newBtn);

      if (sortableInstance) {
        sortableInstance.destroy();
      }
      if (typeof Sortable !== 'undefined') {
        sortableInstance = new Sortable(tabsContainer, {
          animation: 180,
          direction: "horizontal",
          filter: ".new-tab",
          onEnd: (evt) => {
            if (evt.oldIndex !== evt.newIndex && evt.oldIndex < tabs.length && evt.newIndex < tabs.length) {
              const moved = tabs.splice(evt.oldIndex, 1)[0];
              tabs.splice(evt.newIndex, 0, moved);
            }
          }
        });
      }
    }

    function navigateRoute(routeUrl) {
      const activeTab = getActiveTab();
      if (activeTab) {
        navigateTo(activeTab, routeUrl);
      } else {
        createTab(routeUrl, true);
      }
    }

    // Navigation Controls
    document.getElementById("back-btn").onclick = () => {
      const activeTab = getActiveTab();
      try {
        if (activeTab && activeTab.frame.contentWindow) {
          activeTab.frame.contentWindow.history.back();
        }
      } catch(e) {}
    };

    document.getElementById("fwd-btn").onclick = () => {
      const activeTab = getActiveTab();
      try {
        if (activeTab && activeTab.frame.contentWindow) {
          activeTab.frame.contentWindow.history.forward();
        }
      } catch(e) {}
    };

    document.getElementById("reload-btn").onclick = () => {
      const activeTab = getActiveTab();
      if (activeTab) {
        navigateTo(activeTab, activeTab.url);
      }
    };

    // Address Bar Interactive Browser-like Behaviors
    addressBar.addEventListener("focus", () => {
      const activeTab = getActiveTab();
      const url = activeTab ? activeTab.url : "";
      const clean = activeTab ? unwrapUrl(url) : "";
      const isBuiltIn = isAthyxBuiltInTab(url);

      if (isBuiltIn) {
        const displayUrl = clean || "ath://hometab";
        addressBar.dataset.builtinUrl = displayUrl;
        addressBar.placeholder = displayUrl;
        addressBar.value = "";
        addressBar.classList.add("built-in-focused");
      } else {
        addressBar.classList.remove("built-in-focused");
        setTimeout(() => {
          if (document.activeElement === addressBar) {
            addressBar.select();
          }
        }, 10);
      }
    });

    addressBar.addEventListener("input", () => {
      const activeTab = getActiveTab();
      const isBuiltIn = isAthyxBuiltInTab(activeTab ? activeTab.url : "");

      if (isBuiltIn) {
        if (addressBar.value.length === 0) {
          addressBar.placeholder = addressBar.dataset.builtinUrl || (activeTab ? unwrapUrl(activeTab.url) : "ath://hometab");
          addressBar.classList.add("built-in-focused");
        } else {
          addressBar.classList.add("built-in-focused");
        }
      }
    });

    addressBar.addEventListener("blur", () => {
      addressBar.classList.remove("built-in-focused");
      const activeTab = getActiveTab();
      const url = activeTab ? activeTab.url : "";
      const clean = activeTab ? unwrapUrl(url) : "";
      const isBuiltIn = isAthyxBuiltInTab(url);

      if (isBuiltIn) {
        const displayUrl = clean || "ath://hometab";
        addressBar.value = displayUrl;
        addressBar.placeholder = displayUrl;
      } else {
        if (addressBar.value.trim() === "") {
          addressBar.value = clean || "";
        }
        addressBar.placeholder = "Search or enter URL...";
      }
    });

    addressBar.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        const val = addressBar.value.trim();
        const activeTab = getActiveTab();
        addressBar.blur();
        if (val && activeTab) {
          navigateTo(activeTab, val);
        }
      } else if (e.key === "Escape") {
        e.preventDefault();
        const activeTab = getActiveTab();
        const clean = activeTab ? unwrapUrl(activeTab.url) : "";
        addressBar.value = clean || "ath://hometab";
        addressBar.blur();
      }
    });

    document.getElementById("open-new-window-btn").onclick = () => {
      const activeTab = getActiveTab();
      if (activeTab && activeTab.frame.src) {
        window.open(activeTab.frame.src, "_blank");
      }
    };

    document.getElementById("devtools-btn").onclick = () => {
      const activeTab = getActiveTab();
      if (!activeTab || !activeTab.frame.contentWindow) return;
      try {
        const win = activeTab.frame.contentWindow;
        if (win.eruda) {
          win.eruda.destroy();
          delete win.eruda;
        } else {
          const s = win.document.createElement("script");
          s.src = "https://cdn.jsdelivr.net/npm/eruda";
          s.onload = () => {
            if (win.eruda) { win.eruda.init(); win.eruda.show(); }
          };
          win.document.head.appendChild(s);
        }
      } catch(e) {
        alert("Developer tools cannot be attached to cross-origin frames.");
      }
    };

    // Message handler for inter-frame communication
    window.addEventListener("message", (event) => {
      if (!event.data) return;
      if (event.data.type === "navigate" && event.data.url) {
        const activeTab = getActiveTab();
        if (activeTab) navigateTo(activeTab, event.data.url);
      } else if (event.data.action === "navigate" && event.data.tab) {
        navigateRoute("ath://" + event.data.tab);
      } else if (event.data.action === "athyx_game_active") {
        // Track game active state and title per tab source frame
        const senderTab = tabs.find(t => t.frame && t.frame.contentWindow === event.source);
        if (senderTab) {
          senderTab.isGameActive = !!event.data.active;
          if (event.data.active && event.data.title) {
            senderTab.originalTitle = senderTab.originalTitle || senderTab.title;
            senderTab.title = event.data.title;
          } else if (!event.data.active && senderTab.originalTitle) {
            senderTab.title = senderTab.originalTitle;
          }
        }
        updateTabsUI();

        const activeTab = getActiveTab();
        if (activeTab && activeTab.isGameActive) {
          isGameFullscreenActive = true;
          dockNav.classList.add("dock-game-hidden");
        } else {
          isGameFullscreenActive = false;
          dockNav.classList.remove("dock-game-hidden");
          showDock();
        }
      } else if (event.data.action === "athyx_dock_position_change") {
        setDockPosition(event.data.position || "bottom");
      } else if (event.data.action === "athyx_compact_dock_change") {
        setCompactDock(!!event.data.compact);
      }
    });

    // WISP Proxy Settings Modal
    const wispModal = document.getElementById("wisp-settings-modal");
    document.getElementById("wisp-settings-btn").onclick = () => {
      wispModal.classList.remove("hidden");
      loadWisps();
    };
    document.getElementById("close-wisp-modal").onclick = () => wispModal.classList.add("hidden");
    document.getElementById("close-wisp-modal-footer").onclick = () => wispModal.classList.add("hidden");

    let selectedWispUrl = null;
    async function loadWisps() {
      const container = document.getElementById("dynamic-wisps-container");
      try {
        const res = await fetch("https://cdn.jsdelivr.net/gh/daniil-athyx/Athyx-Network@main./wisp.txt");
        if (!res.ok) throw new Error("fetch failed");
        const txt = await res.text();
        const urls = txt.split("\n").map(l => l.trim()).filter(l => l.startsWith("ws"));
        container.innerHTML = "";
        const cur = localStorage.getItem("proxServer") || (typeof _CONFIG !== 'undefined' ? _CONFIG.wispurl : "wss://new-server.baylib.top/connection/");
        urls.forEach(u => {
          const opt = document.createElement("div");
          opt.className = `wisp-option ${u === cur ? "selected" : ""}`;
          opt.innerHTML = `<div class="wisp-option-name">${new URL(u).hostname}</div>`;
          opt.onclick = () => {
            document.querySelectorAll(".wisp-option").forEach(o => o.classList.remove("selected"));
            opt.classList.add("selected");
            selectedWispUrl = u;
            document.getElementById("apply-wisp-btn").removeAttribute("disabled");
          };
          container.appendChild(opt);
        });
      } catch(e) {
        container.innerHTML = '<div style="font-size:13px; color:var(--text-muted); padding:10px;">Using active WISP proxy: wss://new-server.baylib.top/connection/</div>';
      }
    }

    document.getElementById("apply-wisp-btn").onclick = () => {
      if (selectedWispUrl) {
        localStorage.setItem("proxServer", selectedWispUrl);
        if (bareMuxConn) {
          bareMuxConn.setTransport('/scramjet/Ep/index.mjs', [{ wisp: selectedWispUrl }]);
        }
        wispModal.classList.add("hidden");
      }
    };

    // Update log modal
    fetch('update_log.json?v=' + Date.now())
      .then(res => res.json())
      .then(data => {
        if (!data || !data.updateId) return;
        const lastSeen = localStorage.getItem('athyx_last_update');
        if (lastSeen !== data.updateId) {
          const changesDiv = document.getElementById('update-changes');
          changesDiv.innerHTML = '<ul style="margin: 0; padding-left: 20px;">' + data.changes.map(c => `<li>${c}</li>`).join('') + '</ul>';
          const modal = document.getElementById('update-modal');
          modal.classList.add('open');
          modal.setAttribute('aria-hidden', 'false');
          document.getElementById('update-close').onclick = () => {
            modal.classList.remove('open');
            modal.setAttribute('aria-hidden', 'true');
            localStorage.setItem('athyx_last_update', data.updateId);
          };
        }
      }).catch(e => console.log('No update log found', e));

    // Panic Key
    window.addEventListener("keydown", (e) => {
      const panicEnabled = localStorage.getItem("athyx_panic_enabled") !== "false";
      if (!panicEnabled) return;
      const panicKey = localStorage.getItem("athyx_panic_key");
      const panicUrl = localStorage.getItem("athyx_panic_url") || "https://www.google.com";
      if (panicKey && (e.key === panicKey || e.code === panicKey)) {
        window.location.href = panicUrl;
      }
    });



    // Autohide Bottom/Side Dock Logic & Position Settings
    let dockHideTimeout = null;
    let isMouseOverDock = false;
    let isGameFullscreenActive = false;
    const dockTriggerZone = document.getElementById("dockTriggerZone");
    let currentDockPosition = localStorage.getItem("athyx_dock_position") || "bottom";

    function setCompactDock(isCompact) {
      if (isCompact) {
        dockNav.classList.add("dock-compact");
      } else {
        dockNav.classList.remove("dock-compact");
      }
    }

    function setDockPosition(pos) {
      if (pos !== "bottom" && pos !== "left" && pos !== "right") pos = "bottom";
      currentDockPosition = pos;
      localStorage.setItem("athyx_dock_position", pos);

      dockNav.classList.remove("dock-pos-left", "dock-pos-right");
      if (dockTriggerZone) dockTriggerZone.classList.remove("trigger-pos-left", "trigger-pos-right");

      if (pos === "left") {
        dockNav.classList.add("dock-pos-left");
        if (dockTriggerZone) dockTriggerZone.classList.add("trigger-pos-left");
      } else if (pos === "right") {
        dockNav.classList.add("dock-pos-right");
        if (dockTriggerZone) dockTriggerZone.classList.add("trigger-pos-right");
      }
      showDock();
    }

    function showDock() {
      if (isGameFullscreenActive) return;
      if (dockHideTimeout) {
        clearTimeout(dockHideTimeout);
        dockHideTimeout = null;
      }
      dockNav.classList.remove("dock-hidden");
    }

    function hideDock() {
      if (isMouseOverDock || isGameFullscreenActive) return;
      if (dockHideTimeout) {
        clearTimeout(dockHideTimeout);
        dockHideTimeout = null;
      }
      dockNav.classList.add("dock-hidden");
    }

    function handleGlobalMouseMove(clientX, clientY) {
      if (isGameFullscreenActive) return;

      let shouldShow = false;
      if (currentDockPosition === "left") {
        shouldShow = clientX <= 85;
      } else if (currentDockPosition === "right") {
        shouldShow = clientX >= window.innerWidth - 85;
      } else {
        // bottom
        shouldShow = clientY >= window.innerHeight - 85;
      }

      if (shouldShow) {
        showDock();
      } else {
        hideDock();
      }
    }

    function bindIframeMouseEvents(iframe) {
      try {
        const win = iframe.contentWindow;
        const doc = iframe.contentDocument || win?.document;
        if (doc) {
          doc.addEventListener("mousemove", (e) => {
            const rect = iframe.getBoundingClientRect();
            handleGlobalMouseMove(e.clientX + rect.left, e.clientY + rect.top);
          }, { passive: true });
        }
      } catch(e) {}
    }

    window.addEventListener("mousemove", (e) => {
      handleGlobalMouseMove(e.clientX, e.clientY);
    }, { passive: true });

    window.addEventListener("touchstart", (e) => {
      const touch = e.touches[0];
      if (touch) handleGlobalMouseMove(touch.clientX, touch.clientY);
    }, { passive: true });

    if (dockTriggerZone) {
      dockTriggerZone.addEventListener("mouseenter", showDock);
      dockTriggerZone.addEventListener("mousemove", showDock);
    }

    dockNav.addEventListener("mouseenter", () => {
      isMouseOverDock = true;
      showDock();
    });

    dockNav.addEventListener("mouseleave", () => {
      isMouseOverDock = false;
      hideDock();
    });

    // Apply saved dock settings on startup
    setDockPosition(currentDockPosition);
    const savedCompact = localStorage.getItem("athyx_compact_dock") === "true";
    setCompactDock(savedCompact);
    // Keep dock hidden by default on load
    hideDock();

    // Initialize initial tab with home
    createTab('ath://home', true);
  </script>
</body>

</html>
")
